const START_TARGET_USAGE =
  'Usage: --target <directionRef>|<sessionId>:<variantId> (example: --target warm-editorial-green)';
const GET_USAGE =
  'Usage: rivet variants get <directionRef>|last|[<projectId>/]<sessionId>:<variantId> [--detail] [--project <path>]';

type VariantTarget = {
  kind: 'variant';
  sessionId: string;
  variantId: string;
};

const resolveStartTarget = async (args: {
  projectPath: string;
  raw: string | undefined;
}): Promise<
  { ok: true; target?: VariantTarget } | { ok: false; result: CliCommandResult }
> => {
  if (args.raw === undefined) return { ok: true };
  const resolved = await resolveDirectionTarget({
    command: START_COMMAND,
    projectPath: args.projectPath,
    input: args.raw,
    usage: START_TARGET_USAGE,
  });
  if (!resolved.ok) return resolved;
  const { sessionId, variantId } = resolved.target;
  return { ok: true, target: { kind: 'variant', sessionId, variantId } };
};

const parseJsonFlag = (
  command: string,
  name: string,
  raw: string | undefined,
): { ok: true; value?: unknown } | { ok: false; result: CliCommandResult } => {
  if (raw === undefined) {
    return { ok: true };
  }
  try {
    return { ok: true, value: JSON.parse(raw) };
  } catch {
    return {
      ok: false,
      result: errorResult(
        command,
        'USAGE_ERROR',
        `--${name} must be valid JSON.`,
      ),
    };
  }
};

const parseStartBriefsFlag = (
  raw: string | undefined,
):
  | { ok: true; briefs?: VariantDirectionBrief[] }
  | { ok: false; result: CliCommandResult } => {
  const parsed = parseJsonFlag(START_COMMAND, 'briefs', raw);
  if (!parsed.ok) return parsed;
  if (parsed.value === undefined) return { ok: true };
  if (!Array.isArray(parsed.value) || parsed.value.length === 0) {
    return {
      ok: false,
      result: errorResult(
        START_COMMAND,
        'USAGE_ERROR',
        '--briefs must be a non-empty JSON array of {label, body} objects.',
      ),
    };
  }
  const countWords = (value: string): number =>
    value.trim().split(/\s+/).filter(Boolean).length;
  const isValidBrief = (brief: unknown): brief is VariantDirectionBrief => {
    if (!brief || typeof brief !== 'object') return false;
    const candidate = brief as Partial<VariantDirectionBrief>;
    return (
      typeof candidate.label === 'string' &&
      candidate.label.trim().length > 0 &&
      countWords(candidate.label) <= MAX_DIRECTION_TITLE_WORDS &&
      typeof candidate.body === 'string' &&
      candidate.body.trim().length > 0 &&
      countWords(candidate.body) <= MAX_DIRECTION_SUBTITLE_WORDS &&
      (candidate.notes === undefined ||
        (typeof candidate.notes === 'string' &&
          candidate.notes.trim().length > 0 &&
          candidate.notes.length <= 4000)) &&
      (candidate.visualReferenceUrl === undefined ||
        typeof candidate.visualReferenceUrl === 'string')
    );
  };
  if (!parsed.value.every(isValidBrief)) {
    return {
      ok: false,
      result: errorResult(
        START_COMMAND,
        'USAGE_ERROR',
        '--briefs entries require a 1–5 word label and a 1–10 word body.',
      ),
    };
  }
  const normalizedLabels = parsed.value.map((brief) =>
    brief.label.trim().toLowerCase().replace(/\s+/g, ' '),
  );
  if (new Set(normalizedLabels).size !== normalizedLabels.length) {
    return {
      ok: false,
      result: errorResult(
        START_COMMAND,
        'USAGE_ERROR',
        '--briefs labels must be distinct.',
      ),
    };
  }
  return { ok: true, briefs: parsed.value };
};

const parseStartFilesFlag = (
  raw: string | undefined,
): { ok: true; files?: string[] } | { ok: false; result: CliCommandResult } => {
  const parsed = parseJsonFlag(START_COMMAND, 'files', raw);
  if (!parsed.ok) return parsed;
  if (parsed.value === undefined) return { ok: true };
  if (
    !Array.isArray(parsed.value) ||
    parsed.value.length > MAX_RELEVANT_FILES ||
    parsed.value.some(
      (file) => typeof file !== 'string' || file.trim().length === 0,
    )
  ) {
    return {
      ok: false,
      result: errorResult(
        START_COMMAND,
        'USAGE_ERROR',
        `--files must be a JSON array of at most ${MAX_RELEVANT_FILES} non-empty paths.`,
      ),
    };
  }
  return {
    ok: true,
    files: Array.from(new Set(parsed.value.map((file) => file.trim()))),
  };
};

const parseStartContextImagesFlag = (
  raw: string | undefined,
):
  { ok: true; images?: string[] } | { ok: false; result: CliCommandResult } => {
  const parsed = parseJsonFlag(START_COMMAND, 'context-images', raw);
  if (!parsed.ok) return parsed;
  if (parsed.value === undefined) return { ok: true };
  if (
    !Array.isArray(parsed.value) ||
    parsed.value.length === 0 ||
    parsed.value.some(
      (file) => typeof file !== 'string' || file.trim().length === 0,
    )
  ) {
    return {
      ok: false,
      result: errorResult(
        START_COMMAND,
        'USAGE_ERROR',
        '--context-images must be a non-empty JSON array of image file paths.',
      ),
    };
  }
  const images: string[] = [];
  let totalBytes = 0;
  for (const rawPath of parsed.value as string[]) {
    const imagePath = path.resolve(rawPath.trim());
    const mimeType = CONTEXT_IMAGE_MIME_BY_EXTENSION.get(
      path.extname(imagePath).toLowerCase(),
    );
    if (!mimeType) {
      return {
        ok: false,
        result: errorResult(
          START_COMMAND,
          'USAGE_ERROR',
          `--context-images supports ${[...CONTEXT_IMAGE_MIME_BY_EXTENSION.keys()].join(', ')} files; got ${rawPath}`,
        ),
      };
    }
    let buffer: Buffer;
    try {
      buffer = fs.readFileSync(imagePath);
    } catch {
      return {
        ok: false,
        result: errorResult(
          START_COMMAND,
          'USAGE_ERROR',
          `--context-images path is not readable: ${rawPath}`,
        ),
      };
    }
    if (buffer.length === 0 || buffer.length > MAX_CONTEXT_IMAGE_BYTES) {
      return {
        ok: false,
        result: errorResult(
          START_COMMAND,
          'USAGE_ERROR',
          `--context-images files must be 1 byte – ${MAX_CONTEXT_IMAGE_BYTES / (1024 * 1024)}MB; ${rawPath} is ${buffer.length} bytes.`,
        ),
      };
    }
    totalBytes += buffer.length;
    if (totalBytes > MAX_CONTEXT_IMAGE_TOTAL_BYTES) {
      return {
        ok: false,
        result: errorResult(
          START_COMMAND,
          'USAGE_ERROR',
          `--context-images combined size must be at most ${MAX_CONTEXT_IMAGE_TOTAL_BYTES / (1024 * 1024)}MB.`,
        ),
      };
    }
    images.push(`data:${mimeType};base64,${buffer.toString('base64')}`);
  }
  return { ok: true, images };
};

const parseStartReferencePicksFlag = (
  raw: string | undefined,
):
  | { ok: true; referencePicks?: ReferencePicks }
  | { ok: false; result: CliCommandResult } => {
  const parsed = parseJsonFlag(START_COMMAND, 'reference-picks', raw);
  if (!parsed.ok) return parsed;
  if (parsed.value === undefined) return { ok: true };
  const picks = referencePicksSchema.safeParse(parsed.value);
  if (!picks.success)
    return {
      ok: false,
      result: errorResult(
        START_COMMAND,
        'USAGE_ERROR',
        `--reference-picks must be {"profileId": "<uuid>", "picks": [{"key": "<key>", "reason": "<why>"}]} with 1–3 distinct keys: ${picks.error.issues.map((issue) => issue.message).join('; ')}`,
      ),
    };
  return { ok: true, referencePicks: picks.data };
};

const parseStartContextAssetsFlag = (
  raw: string | undefined,
):
  | { ok: true; assets?: ContextAssetInput[] }
  | { ok: false; result: CliCommandResult } => {
  const parsed = parseJsonFlag(START_COMMAND, 'context-assets', raw);
  if (!parsed.ok) return parsed;
  if (parsed.value === undefined) return { ok: true };
  if (
    !Array.isArray(parsed.value) ||
    parsed.value.length === 0 ||
    parsed.value.length > CONTEXT_ASSET_MAX_ITEMS
  ) {
    return {
      ok: false,
      result: errorResult(
        START_COMMAND,
        'USAGE_ERROR',
        `--context-assets must be a JSON array of 1–${CONTEXT_ASSET_MAX_ITEMS} local asset paths or {path, label} objects.`,
      ),
    };
  }

  const assets: ContextAssetInput[] = [];
  let totalBytes = 0;
  for (const entry of parsed.value) {
    const candidate =
      typeof entry === 'string'
        ? { path: entry }
        : entry && typeof entry === 'object'
          ? entry
          : undefined;
    const normalized =
      candidate && 'path' in candidate && typeof candidate.path === 'string'
        ? { ...candidate, path: path.resolve(candidate.path.trim()) }
        : candidate;
    const validated = contextAssetInputSchema.safeParse(normalized);
    if (!validated.success) {
      const message = validated.error.issues[0]?.message ?? 'invalid entry';
      return {
        ok: false,
        result: errorResult(
          START_COMMAND,
          'USAGE_ERROR',
          `--context-assets entry is invalid: ${message}.`,
        ),
      };
    }
    try {
      totalBytes += inspectContextAssetSource(validated.data).sizeBytes;
    } catch (error) {
      return {
        ok: false,
        result: errorResult(START_COMMAND, 'USAGE_ERROR', errorMessage(error)),
      };
    }
    assets.push(validated.data);
  }
  if (totalBytes > MAX_CONTEXT_ASSET_TOTAL_BYTES) {
    return {
      ok: false,
      result: errorResult(
        START_COMMAND,
        'USAGE_ERROR',
        `--context-assets exceed total size limit (${totalBytes} > ${MAX_CONTEXT_ASSET_TOTAL_BYTES}).`,
      ),
    };
  }
  if (new Set(assets.map((asset) => asset.path)).size !== assets.length) {
    return {
      ok: false,
      result: errorResult(
        START_COMMAND,
        'USAGE_ERROR',
        '--context-assets contains duplicate paths.',
      ),
    };
  }
  return { ok: true, assets };
};

const parseStartReferencePagesFlag = (
  raw: string | undefined,
):
  | { ok: true; pages?: Array<{ url: string; note?: string }> }
  | { ok: false; result: CliCommandResult } => {
  const parsed = parseJsonFlag(START_COMMAND, 'reference-pages', raw);
  if (!parsed.ok) return parsed;
  if (parsed.value === undefined) return { ok: true };
  const usage = {
    ok: false as const,
    result: errorResult(
      START_COMMAND,
      'USAGE_ERROR',
      `--reference-pages must be a JSON array of 1–${MAX_REFERENCE_PAGES} http(s) URLs or {url, note} objects.`,
    ),
  };
  if (
    !Array.isArray(parsed.value) ||
    parsed.value.length === 0 ||
    parsed.value.length > MAX_REFERENCE_PAGES
  ) {
    return usage;
  }
  const pages: Array<{ url: string; note?: string }> = [];
  for (const entry of parsed.value) {
    const candidate =
      typeof entry === 'string'
        ? { url: entry }
        : entry && typeof entry === 'object'
          ? (entry as { url?: unknown; note?: unknown })
          : undefined;
    const url = typeof candidate?.url === 'string' ? candidate.url.trim() : '';
    if (!/^https?:\/\//i.test(url)) {
      return usage;
    }
    const note =
      typeof candidate?.note === 'string' && candidate.note.trim()
        ? candidate.note.trim()
        : undefined;
    pages.push({ url, ...(note ? { note } : {}) });
  }
  return { ok: true, pages };
};

const parseStartReferenceVideosFlag = (
  raw: string | undefined,
):
  | { ok: true; videos?: Array<{ path: string; note?: string }> }
  | { ok: false; result: CliCommandResult } => {
  const parsed = parseJsonFlag(START_COMMAND, 'reference-videos', raw);
  if (!parsed.ok) return parsed;
  if (parsed.value === undefined) return { ok: true };
  const usage = (message: string) => ({
    ok: false as const,
    result: errorResult(START_COMMAND, 'USAGE_ERROR', message),
  });
  if (
    !Array.isArray(parsed.value) ||
    parsed.value.length === 0 ||
    parsed.value.length > MAX_REFERENCE_VIDEOS
  ) {
    return usage(
      `--reference-videos must be a JSON array of 1–${MAX_REFERENCE_VIDEOS} local video file paths or {path, note} objects.`,
    );
  }
  const videos: Array<{ path: string; note?: string }> = [];
  for (const entry of parsed.value) {
    const candidate =
      typeof entry === 'string'
        ? { path: entry }
        : entry && typeof entry === 'object'
          ? (entry as { path?: unknown; note?: unknown })
          : undefined;
    const rawPath =
      typeof candidate?.path === 'string' ? candidate.path.trim() : '';
    if (!rawPath) {
      return usage('--reference-videos entries need a non-empty path.');
    }
    const videoPath = path.resolve(rawPath);
    if (
      !REFERENCE_VIDEO_EXTENSIONS.has(path.extname(videoPath).toLowerCase())
    ) {
      return usage(
        `--reference-videos supports ${[...REFERENCE_VIDEO_EXTENSIONS].join(', ')} files; got ${rawPath}`,
      );
    }
    if (!fs.existsSync(videoPath)) {
      return usage(`--reference-videos path is not readable: ${rawPath}`);
    }
    const note =
      typeof candidate?.note === 'string' && candidate.note.trim()
        ? candidate.note.trim()
        : undefined;
    videos.push({ path: videoPath, ...(note ? { note } : {}) });
  }
  return { ok: true, videos };
};

const parseStartRunLabelFlag = (
  raw: string | undefined,
):
  { ok: true; runLabel?: string } | { ok: false; result: CliCommandResult } => {
  if (raw === undefined) return { ok: true };
  const runLabel = raw.trim();
  const wordCount = runLabel.split(/\s+/).filter(Boolean).length;
  if (
    runLabel.length === 0 ||
    runLabel.length > RUN_LABEL_MAX_LENGTH ||
    wordCount > RUN_LABEL_MAX_WORDS
  ) {
    return {
      ok: false,
      result: errorResult(
        START_COMMAND,
        'USAGE_ERROR',
        `--run-label must contain 1–${RUN_LABEL_MAX_WORDS} words and at most ${RUN_LABEL_MAX_LENGTH} characters.`,
      ),
    };
  }
  return { ok: true, runLabel };
};

const handleVariantsStart = async (
  args: string[],
  options: VariantsCommandOptions,
): Promise<CliCommandResult> => {
  const context = parseCommandContext(START_COMMAND, args, START_FLAG_SPEC);
  if (isCommandResult(context)) {
    return context;
  }
  const instruction = stringFlag(context.flags, 'instruction');
  if (!instruction?.trim()) {
    return errorResult(
      START_COMMAND,
      'USAGE_ERROR',
      'Usage: rivet variants start --instruction <text> [--run-label <text>] [--briefs <json>] [--count N] [--fidelity low|medium|high] [--element <selector>] [--files <json>] [--fresh] [--context-images <json>] [--context-assets <json>] [--reference-pages <json>] [--reference-videos <json>] [--reference-picks <json>] [--target <directionRef>|<sessionId>:<variantId>]',
    );
  }
  if (context.flags.errors.length > 0) {
    return errorResult(
      START_COMMAND,
      'USAGE_ERROR',
      context.flags.errors.join('; '),
    );
  }
  const parsedBriefs = parseStartBriefsFlag(
    stringFlag(context.flags, 'briefs'),
  );
  const profileMode = stringFlag(context.flags, 'profile');
  let guidanceSelection: GuidanceSelection;
  try {
    guidanceSelection = guidanceSelectionFromFlags(context.flags);
  } catch (error) {
    return errorResult(
      START_COMMAND,
      'USAGE_ERROR',
      errorMessage(error, 'Invalid saved context selection'),
    );
  }
  if (
    profileMode !== undefined &&
    profileMode !== 'auto' &&
    profileMode !== 'off'
  )
    return errorResult(
      START_COMMAND,
      'USAGE_ERROR',
      '--profile must be auto or off',
    );
  if (!parsedBriefs.ok) return parsedBriefs.result;
  const parsedRunLabel = parseStartRunLabelFlag(
    stringFlag(context.flags, 'run-label'),
  );
  if (!parsedRunLabel.ok) return parsedRunLabel.result;
  const parsedFiles = parseStartFilesFlag(stringFlag(context.flags, 'files'));
  if (!parsedFiles.ok) return parsedFiles.result;
  const parsedContextImages = parseStartContextImagesFlag(
    stringFlag(context.flags, 'context-images'),
  );
  if (!parsedContextImages.ok) return parsedContextImages.result;
  const parsedReferencePicks = parseStartReferencePicksFlag(
    stringFlag(context.flags, 'reference-picks'),
  );
  if (!parsedReferencePicks.ok) return parsedReferencePicks.result;
  const parsedContextAssets = parseStartContextAssetsFlag(
    stringFlag(context.flags, 'context-assets'),
  );
  if (!parsedContextAssets.ok) return parsedContextAssets.result;
  const parsedReferencePages = parseStartReferencePagesFlag(
    stringFlag(context.flags, 'reference-pages'),
  );
  if (!parsedReferencePages.ok) return parsedReferencePages.result;
  const parsedReferenceVideos = parseStartReferenceVideosFlag(
    stringFlag(context.flags, 'reference-videos'),
  );
  if (!parsedReferenceVideos.ok) return parsedReferenceVideos.result;
  const rawFidelity = stringFlag(context.flags, 'fidelity')
    ?.trim()
    .toLowerCase();
  if (rawFidelity !== undefined && !WORKER_FIDELITY_VALUES.has(rawFidelity)) {
    return errorResult(
      START_COMMAND,
      'USAGE_ERROR',
      '--fidelity must be one of: low, medium, high.',
    );
  }
  const fidelity = rawFidelity as 'low' | 'medium' | 'high' | undefined;
  const rawWorkerProvider = stringFlag(context.flags, 'worker-provider')
    ?.trim()
    .toLowerCase();
  if (
    rawWorkerProvider !== undefined &&
    !WORKER_PROVIDER_VALUES.has(rawWorkerProvider)
  ) {
    return errorResult(
      START_COMMAND,
      'USAGE_ERROR',
      '--worker-provider must be one of: claude, codex, cursor.',
    );
  }
  const workerProvider = rawWorkerProvider as
    'claude' | 'codex' | 'cursor' | undefined;
  const workerModel = stringFlag(context.flags, 'worker-model')?.trim();
  if (workerModel !== undefined && workerModel.length === 0) {
    return errorResult(
      START_COMMAND,
      'USAGE_ERROR',
      '--worker-model requires a non-empty model id.',
    );
  }
  const isFreshStart = booleanFlag(context.flags, 'fresh');
  if (context.handoff && !parsedBriefs.briefs) {
    return errorResult(
      START_COMMAND,
      'USAGE_ERROR',
      'Agent-attributed variants starts require --briefs with one AI-authored title/subtitle per direction.',
    );
  }
  if (context.handoff && !parsedRunLabel.runLabel) {
    return errorResult(
      START_COMMAND,
      'USAGE_ERROR',
      'Agent-attributed variants starts require --run-label with an AI-authored 1–3 word batch summary.',
    );
  }
  const explicitCount = integerFlag(context.flags, 'count');
  if (
    explicitCount !== undefined &&
    parsedBriefs.briefs &&
    explicitCount !== parsedBriefs.briefs.length
  ) {
    return errorResult(
      START_COMMAND,
      'USAGE_ERROR',
      '--count must match --briefs length when both are provided.',
    );
  }
  const isFresh = isFreshStart;
  const parsedTarget = await resolveStartTarget({
    projectPath: context.projectPath,
    raw: stringFlag(context.flags, 'target'),
  });
  if (!parsedTarget.ok) return parsedTarget.result;
  if (isFresh && parsedTarget.target) {
    return errorResult(
      START_COMMAND,
      'USAGE_ERROR',
      '--fresh cannot be combined with --target; start fresh generation from the base project.',
    );
  }
  const elementSelector = stringFlag(context.flags, 'element');
  const isTargetedRequest =
    !isFresh && Boolean(parsedTarget.target || elementSelector);
  const defaultCount = isTargetedRequest
    ? DEFAULT_TARGETED_VARIANT_REQUEST_COUNT
    : DEFAULT_BROAD_VARIANT_REQUEST_COUNT;
  const count = parsedBriefs.briefs?.length ?? explicitCount ?? defaultCount;

  const accountId = getConfigManager().getUserId();
  const accountChangedResult = () =>
    errorResult(
      START_COMMAND,
      'OPERATION_FAILED',
      'Rivet account changed during generation. Inspect the project status before retrying.',
    );
  const handoffPromise = withCallerSessionModel(context.handoff);
  const attached = await preflightGeneration({
    command: START_COMMAND,
    context,
    io: options.io ?? processCliIO,
    dependencies: options.runtimeDependencies,
  });
  if (!isAttached(attached)) {
    return attached;
  }

  if (getConfigManager().getUserId() !== accountId)
    return accountChangedResult();
  const target = parsedTarget.target;
  const traceId = randomUUID();
  const agentRunId = randomUUID();
  const handoff = await handoffPromise;
  try {
    const response = await requestServer<{
      success?: boolean;
      traceId?: string;
      agentRunId?: string;
      profileContext?: import('../../types/design-profile').ProfileContextResult;
      guidance?: Pick<GuidanceDocument, 'id' | 'title'>[];
      guidanceWarning?: GuidanceWarning;
      kind?: string;
    }>(attached, '/api/variants/inline', {
      expectedAccountId: accountId ?? undefined,
      method: 'POST',
      body: {
        changes: [
          {
            kind: 'comment',
            element: elementSelector
              ? elementRefFromSelector(elementSelector)
              : wholePageElement(),
            instruction,
            ...(target ? { target } : {}),
            ...(parsedContextImages.images
              ? { images: parsedContextImages.images }
              : {}),
            variantRequest: {
              guidanceSelection,
              ...(profileMode ? { profile: profileMode } : {}),
              count,
              ...(parsedRunLabel.runLabel
                ? { runLabel: parsedRunLabel.runLabel }
                : {}),
              ...(fidelity ? { fidelity } : {}),
              ...(parsedBriefs.briefs ? { briefs: parsedBriefs.briefs } : {}),
              ...(parsedContextAssets.assets
                ? { contextAssets: parsedContextAssets.assets }
                : {}),
              ...(isFresh ? { mode: 'zero_to_one' as const } : {}),
              ...(parsedReferencePages.pages
                ? { referencePages: parsedReferencePages.pages }
                : {}),
              ...(parsedReferenceVideos.videos
                ? { referenceVideos: parsedReferenceVideos.videos }
                : {}),
              ...(parsedReferencePicks.referencePicks
                ? { referencePicks: parsedReferencePicks.referencePicks }
                : {}),
            },
          },
        ],
        sourceFiles: parsedFiles.files ?? [],
        ...(target ? { target } : {}),
        traceId,
        agentRunId,
        initiator: initiatorFor(handoff),
        ...(workerProvider || workerModel
          ? {
              workerSelection: {
                ...(workerProvider ? { provider: workerProvider } : {}),
                ...(workerModel ? { model: workerModel } : {}),
              },
            }
          : {}),
      },
      callerSession: callerSessionOf(context.handoff),
      timeoutMs: VARIANTS_START_REQUEST_TIMEOUT_MS,
    });
    if (getConfigManager().getUserId() !== accountId)
      return accountChangedResult();
    if (response.status !== 200) {
      return serverErrorResult(START_COMMAND, response.status, response.body);
    }
    let status: StatusWithHostWork | null = null;
    try {
      const statusResponse = await requestServer<StatusWithHostWork>(
        attached,
        '/api/cli/status',
      );
      if (statusResponse.status === 200) {
        status = statusResponse.body;
      }
    } catch {
      status = null;
    }
    if (getConfigManager().getUserId() !== accountId)
      return accountChangedResult();
    const nextAction = status
      ? buildHostWorkNextAction(status, {
          callerAgent: handoff?.agent,
          callerModel: handoff?.model,
        })
      : null;
    return okResult(START_COMMAND, {
      ...versionEnvelopeFields(attached.handshake),
      workId: response.body.agentRunId ?? agentRunId,
      traceId: response.body.traceId ?? traceId,
      requestedCount: count,
      queued: true,
      editor: projectEditor({ projectPath: context.projectPath }),
      ...(response.body.guidanceWarning
        ? { guidanceWarning: response.body.guidanceWarning }
        : {}),
      ...(response.body.guidance !== undefined
        ? { guidance: response.body.guidance }
        : {}),
      ...(response.body.profileContext
        ? { profileContext: response.body.profileContext }
        : {}),
      ...(status?.variants?.sessionId
        ? { sessionId: status.variants.sessionId }
        : {}),
      ...(status?.variants?.hostWork
        ? { hostWork: status.variants.hostWork }
        : {}),
      ...(status?.variants?.workerRuntime
        ? { workerRuntime: status.variants.workerRuntime }
        : {}),
      ...(nextAction ? { nextAction } : {}),
    });
  } catch (error) {
    return transportErrorResult(START_COMMAND, error);
  }
};

