const handleVariantsCancel = async (
  args: string[],
): Promise<CliCommandResult> => {
  const context = parseCommandContext(CANCEL_COMMAND, args);
  if (isCommandResult(context)) {
    return context;
  }
  const sessionId = context.flags.positionals[0];
  if (!sessionId) {
    return errorResult(
      CANCEL_COMMAND,
      'USAGE_ERROR',
      'Usage: rivet variants cancel <sessionId>',
    );
  }
  const attached = await attachOrUnavailable(
    CANCEL_COMMAND,
    context.projectPath,
  );
  if (!isAttached(attached)) {
    return attached;
  }
  try {
    const response = await requestServer(
      attached,
      `/api/variants/${encodeURIComponent(sessionId)}/cancel`,
      { method: 'POST', body: { reason: 'cli_cancel' } },
    );
    if (response.status !== 200) {
      return serverErrorResult(CANCEL_COMMAND, response.status, response.body);
    }
    return okResult(CANCEL_COMMAND, response.body);
  } catch (error) {
    return transportErrorResult(CANCEL_COMMAND, error);
  }
};

const resolveActiveSessionId = async (
  attached: AttachedServer,
): Promise<string | null> => {
  const response = await requestServer<{
    active?: boolean;
    sessionId?: string;
  }>(attached, '/api/variants/active');
  if (response.status !== 200 || response.body.active !== true) return null;
  return response.body.sessionId ?? null;
};

const handleVariantsComplete = async (
  args: string[],
): Promise<CliCommandResult> => {
  const context = parseCommandContext(
    COMPLETE_COMMAND,
    args,
    COMPLETE_FLAG_SPEC,
  );
  if (isCommandResult(context)) {
    return context;
  }
  const workItemId = context.flags.positionals[0];
  if (!workItemId) {
    return errorResult(
      COMPLETE_COMMAND,
      'USAGE_ERROR',
      'Usage: rivet variants complete <workId> [--session <sessionId>] [--status succeeded|failed|cancelled] [--output <json>]',
    );
  }
  if (context.flags.errors.length > 0) {
    return errorResult(
      COMPLETE_COMMAND,
      'USAGE_ERROR',
      context.flags.errors.join('; '),
    );
  }
  const status = stringFlag(context.flags, 'status') ?? 'succeeded';
  if (!['succeeded', 'failed', 'cancelled'].includes(status)) {
    return errorResult(
      COMPLETE_COMMAND,
      'USAGE_ERROR',
      '--status must be one of: succeeded, failed, cancelled.',
    );
  }
  const parsedOutput = parseJsonFlag(
    COMPLETE_COMMAND,
    'output',
    stringFlag(context.flags, 'output'),
  );
  if (!parsedOutput.ok) {
    return parsedOutput.result;
  }
  const failureMessage = stringFlag(context.flags, 'error');
  const attached = await attachOrUnavailable(
    COMPLETE_COMMAND,
    context.projectPath,
  );
  if (!isAttached(attached)) {
    return attached;
  }
  try {
    const sessionId =
      stringFlag(context.flags, 'session') ??
      (await resolveActiveSessionId(attached));
    if (!sessionId) {
      return errorResult(
        COMPLETE_COMMAND,
        'OPERATION_FAILED',
        'No active variants session. Pass --session <sessionId>.',
      );
    }
    const response = await requestServer(
      attached,
      `/api/variants/${encodeURIComponent(sessionId)}/work/${encodeURIComponent(workItemId)}/complete`,
      {
        method: 'POST',
        body: {
          status,
          ...(parsedOutput.value !== undefined
            ? { output: parsedOutput.value }
            : {}),
          ...(failureMessage
            ? { error: { code: 'HOST_AGENT_FAILED', message: failureMessage } }
            : {}),
          ...(stringFlag(context.flags, 'title')
            ? { title: stringFlag(context.flags, 'title') }
            : {}),
          ...(stringFlag(context.flags, 'description')
            ? { description: stringFlag(context.flags, 'description') }
            : {}),
        },
      },
    );
    if (response.status !== 200) {
      return serverErrorResult(
        COMPLETE_COMMAND,
        response.status,
        response.body,
      );
    }
    return okResult(COMPLETE_COMMAND, {
      sessionId,
      workItemId,
      result: response.body,
      editor: projectEditor({ projectPath: context.projectPath }),
    });
  } catch (error) {
    return transportErrorResult(COMPLETE_COMMAND, error);
  }
};

const handleSavedVariantGet = async (args: {
  projectId: string;
  sessionId: string;
  variantId: string;
  directionRef?: DirectionRef;
  isDetailed: boolean;
  explicitProjectPath?: string;
}): Promise<CliCommandResult> => {
  try {
    const { ProjectLibrary } = await import('../../services/ProjectLibrary');
    const library = await ProjectLibrary.open();
    try {
      if (args.explicitProjectPath) {
        const owner = library.registry.findByPath(args.explicitProjectPath);
        if (owner?.id !== args.projectId)
          return errorResult(
            GET_COMMAND,
            'WORK_ITEM_NOT_FOUND',
            'The supplied project path does not own this variant reference.',
          );
      }
      const reference = {
        projectId: args.projectId,
        sessionId: args.sessionId,
        variantId: args.variantId,
      };
      const found = args.isDetailed
        ? await library.variant(reference)
        : await library.variantSummary(reference);
      if (!found)
        return errorResult(
          GET_COMMAND,
          'WORK_ITEM_NOT_FOUND',
          'No saved variant exists for this project and reference.',
        );
      const saved = 'detail' in found ? found.detail : found.summary;
      const { manifest, variantDir } = saved;
      const directionRef = args.directionRef ?? manifest.directionRef;
      const kind =
        manifest.artifact.kind === 'diff' ? 'diff' : 'project-created';
      const artifactPath = path.join(
        variantDir,
        manifest.artifact.kind === 'diff'
          ? manifest.artifact.diffPath
          : manifest.artifact.filesPath,
      );
      const variant =
        args.isDetailed && 'detail' in found
          ? {
              ...manifest,
              directionRef,
              kind,
              artifactPath,
              diff: found.detail.diff,
              files: found.detail.files,
              designMarkdown: found.detail.designMarkdown,
            }
          : {
              directionRef,
              sessionId: manifest.sessionId,
              variantId: manifest.variantId,
              status: manifest.status,
              label: manifest.label,
              brief: manifest.brief,
              changedFilesCount: manifest.changedFilesCount,
              kind,
              artifactPath,
            };
      const owner = library.registry.get(args.projectId);
      return okResult(GET_COMMAND, {
        projectId: args.projectId,
        projectPath: found.projectPath,
        variant,
        editor: projectEditor({
          projectPath: owner.projectPath,
          projectId: owner.id,
        }),
      });
    } finally {
      library.close();
    }
  } catch (error) {
    const isMissingProject =
      error instanceof LibraryError && error.code === 'project_not_found';
    return errorResult(
      GET_COMMAND,
      isMissingProject ? 'WORK_ITEM_NOT_FOUND' : 'OPERATION_FAILED',
      errorMessage(error),
    );
  }
};

const handleVariantsGet = async (args: string[]): Promise<CliCommandResult> => {
  const context = parseCommandContext(GET_COMMAND, args, GET_FLAG_SPEC);
  if (isCommandResult(context)) {
    return context;
  }
  const input = context.flags.positionals[0];
  if (
    input === undefined ||
    context.flags.positionals.length !== 1 ||
    context.flags.errors.length > 0
  ) {
    return errorResult(GET_COMMAND, 'USAGE_ERROR', GET_USAGE);
  }
  const resolved = await resolveDirectionTarget({
    command: GET_COMMAND,
    projectPath: context.projectPath,
    input,
    usage: GET_USAGE,
  });
  if (!resolved.ok) return resolved.result;
  const reference = resolved.target;
  if (reference.projectId)
    return handleSavedVariantGet({
      ...reference,
      projectId: reference.projectId,
      isDetailed: context.flags.values.detail === true,
      explicitProjectPath: stringFlag(context.flags, 'project')
        ? context.projectPath
        : undefined,
    });
  const attached = await attachOrUnavailable(GET_COMMAND, context.projectPath);
  if (!isAttached(attached)) {
    return attached;
  }
  const query = new URLSearchParams({ projectPath: context.projectPath });
  const detailPath = `/api/variants/history/${encodeURIComponent(reference.sessionId)}/${encodeURIComponent(reference.variantId)}?${query.toString()}`;
  try {
    const response = await requestServer<Record<string, unknown>>(
      attached,
      detailPath,
    );
    if (response.status !== 200) {
      return serverErrorResult(GET_COMMAND, response.status, response.body);
    }
    return okResult(GET_COMMAND, {
      ...response.body,
      editor: projectEditor({ projectPath: context.projectPath }),
    });
  } catch (error) {
    return transportErrorResult(GET_COMMAND, error);
  }
};

const handleVariantsList = async (
  args: string[],
): Promise<CliCommandResult> => {
  const context = parseCommandContext(LIST_COMMAND, args, LIST_FLAG_SPEC);
  if (isCommandResult(context)) {
    return context;
  }
  const limit = integerFlag(context.flags, 'limit');
  if (context.flags.errors.length > 0) {
    return errorResult(
      LIST_COMMAND,
      'USAGE_ERROR',
      context.flags.errors.join('; '),
    );
  }
  const attached = await attachOrUnavailable(LIST_COMMAND, context.projectPath);
  if (!isAttached(attached)) {
    return attached;
  }
  const isHistory = context.flags.values.history === true;
  const query = new URLSearchParams({
    projectPath: context.projectPath,
    ...(limit ? { limit: String(limit) } : {}),
  });
  const path = isHistory
    ? `/api/variants/history?${query.toString()}`
    : '/api/variants/active';
  try {
    const response = await requestServer(attached, path);
    if (response.status !== 200) {
      return serverErrorResult(LIST_COMMAND, response.status, response.body);
    }
    return okResult(LIST_COMMAND, response.body);
  } catch (error) {
    return transportErrorResult(LIST_COMMAND, error);
  }
};

export const handleVariants = async (
  args: string[],
  options: VariantsCommandOptions = {},
): Promise<CliCommandResult> => {
  const action = args[0];
  const rest = args.slice(1);
  if (action === 'start') {
    return handleVariantsStart(rest, options);
  }
  if (action === 'status') {
    return handleVariantsStatus(rest);
  }
  if (action === 'cancel') {
    return handleVariantsCancel(rest);
  }
  if (action === 'complete') {
    return handleVariantsComplete(rest);
  }
  if (action === 'get') {
    return handleVariantsGet(rest);
  }
  if (action === 'list') {
    return handleVariantsList(rest);
  }
  return errorResult(
    'variants',
    'USAGE_ERROR',
    'Usage: rivet variants <start|status|cancel|complete|get|list> [options]',
  );
};
